// 定义邮件结构体，仅包含主题字段
#[derive(Debug, Clone)]
pub struct Email {
    pub subject: String,
}

impl Email {
    pub fn new(subject: impl Into<String>) -> Self {
        Email {
            subject: subject.into(),
        }
    }
}

// 定义关键词分类器，负责将邮件主题映射到漏斗阶段
pub struct KeywordClassifier {
    // 每个阶段对应的关键词列表，按优先级从高到低排列
    offer_keywords: Vec<String>,
    interview_keywords: Vec<String>,
    written_test_keywords: Vec<String>,
    resume_submission_keywords: Vec<String>,
}

impl KeywordClassifier {
    /// 创建默认的分类器，使用文档中提到的中英文关键词
    pub fn default() -> Self {
        KeywordClassifier {
            offer_keywords: vec![
                "offer".to_string(),
                "录用".to_string(),
                "录取".to_string(),
                "入职".to_string(),
            ],
            interview_keywords: vec![
                "面试".to_string(),
                "interview".to_string(),
                "面谈".to_string(),
            ],
            written_test_keywords: vec![
                "笔试".to_string(),
                "测试".to_string(),
                "test".to_string(),
                "exam".to_string(),
            ],
            resume_submission_keywords: vec![
                "简历".to_string(),
                "申请".to_string(),
                "投递".to_string(),
                "resume".to_string(),
                "apply".to_string(),
            ],
        }
    }

    /// 对邮件主题进行分类，返回对应的阶段
    /// 遵循优先级规则：Offer > 面试 > 笔试 > 投递
    /// 如果无法匹配任何关键词，返回 None
    pub fn classify(&self, subject: &str) -> Option<FunnelStage> {
        let subject_lower = subject.to_lowercase();

        // 按优先级从高到低检查
        if self.contains_any_keyword(&subject_lower, &self.offer_keywords) {
            return Some(FunnelStage::Offer);
        }
        if self.contains_any_keyword(&subject_lower, &self.interview_keywords) {
            return Some(FunnelStage::Interview);
        }
        if self.contains_any_keyword(&subject_lower, &self.written_test_keywords) {
            return Some(FunnelStage::WrittenTest);
        }
        if self.contains_any_keyword(&subject_lower, &self.resume_submission_keywords) {
            return Some(FunnelStage::ResumeSubmission);
        }

        None
    }

    /// 检查主题是否包含任意一个关键词
    fn contains_any_keyword(&self, subject: &str, keywords: &[String]) -> bool {
        keywords.iter().any(|keyword| subject.contains(keyword))
    }
}

// 定义漏斗分析器，负责核心分析逻辑
pub struct FunnelAnalyzer {
    classifier: KeywordClassifier,
}

impl FunnelAnalyzer {
    pub fn new(classifier: KeywordClassifier) -> Self {
        FunnelAnalyzer { classifier }
    }

    /// 分析邮件列表，返回按漏斗顺序排列的阶段计数
    /// 输入：邮件列表
    /// 输出：按漏斗顺序排列的 (阶段, 数量) 键值对列表
    pub fn analyze(&self, emails: &[Email]) -> Vec<(FunnelStage, usize)> {
        // 初始化所有阶段计数为 0
        let mut counts: std::collections::HashMap<FunnelStage, usize> = FunnelStage::all_in_order()
            .map(|stage| (stage, 0))
            .collect();

        // 遍历每封邮件进行分类计数
        for email in emails {
            // 主题为空时不纳入分析
            if email.subject.is_empty() {
                continue;
            }

            if let Some(stage) = self.classifier.classify(&email.subject) {
                *counts.get_mut(&stage).unwrap() += 1;
            }
            // 无法匹配的邮件被视为非招聘邮件，不纳入统计
        }

        // 按漏斗顺序输出结果
        FunnelStage::all_in_order()
            .map(|stage| (stage, counts[&stage]))
            .collect()
    }
}

// 定义报告生成器，负责生成 Markdown 格式的漏斗报告
pub struct ReportGenerator;

impl ReportGenerator {
    /// 生成 Markdown 格式的漏斗报告
    /// 输入：按漏斗顺序排列的阶段计数列表
    /// 输出：格式化的 Markdown 表格文本
    pub fn generate_report(stage_counts: &[(FunnelStage, usize)]) -> String {
        let total = stage_counts
            .iter()
            .map(|(_, count)| count)
            .sum::<usize>();

        if total == 0 {
            return "暂无招聘邮件数据".to_string();
        }

        let mut report = String::new();
        report.push_str("## 招聘漏斗分析报告\n\n");
        report.push_str("| 阶段 | 数量 | 转化率 | 漏斗图 |\n");
        report.push_str("|------|------|--------|--------|\n");

        let max_count = stage_counts
            .iter()
            .map(|(_, count)| *count)
            .max()
            .unwrap_or(1)
            .max(1); // 避免除以零

        let mut previous_count: Option<usize> = None;

        for (stage, count) in stage_counts {
            let label = stage.label();
            let count_str = count.to_string();

            // 计算转化率
            let conversion_rate = match previous_count {
                Some(prev) if prev > 0 => {
                    format!("{:.1}%", (*count as f64 / prev as f64) * 100.0)
                }
                _ => "-".to_string(),
            };

            // 生成漏斗条（使用 █ 字符表示相对数量）
            let bar_length = if max_count > 0 {
                ((*count as f64 / max_count as f64) * 20.0).round() as usize
            } else {
                0
            };
            let bar = "█".repeat(bar_length);

            report.push_str(&format!("| {} | {} | {} | {} |\n", label, count_str, conversion_rate, bar));

            previous_count = Some(*count);
        }

        report
    }
}

// 定义模块主入口，整合所有功能
pub struct RecruitmentFunnelModule {
    analyzer: FunnelAnalyzer,
}

impl RecruitmentFunnelModule {
    pub fn new() -> Self {
        let classifier = KeywordClassifier::default();
        let analyzer = FunnelAnalyzer::new(classifier);
        RecruitmentFunnelModule { analyzer }
    }

    /// 执行完整的漏斗分析流程
    /// 输入：邮件列表
    /// 输出：(阶段计数列表, 漏斗报告文本)
    pub fn process(&self, emails: &[Email]) -> (Vec<(FunnelStage, usize)>, String) {
        let stage_counts = self.analyzer.analyze(emails);
        let report = ReportGenerator::generate_report(&stage_counts);
        (stage_counts, report)
    }
}

