// 定义关键词分类器，负责将邮件主题映射到漏斗阶段
#[derive(Clone)]
pub struct KeywordClassifier {
    // 每个阶段对应的关键词列表，按优先级从高到低排列
    offer_keywords: Vec<String>,
    interview_keywords: Vec<String>,
    written_exam_keywords: Vec<String>,
    resume_keywords: Vec<String>,
}

// 确保 KeywordClassifier 可以在多线程环境下安全使用
unsafe impl Send for KeywordClassifier {}
unsafe impl Sync for KeywordClassifier {}

impl KeywordClassifier {
    /// 创建默认的分类器，使用中英文关键词
    pub fn default() -> Self {
        KeywordClassifier {
            offer_keywords: vec![
                "offer".to_string(),
                "录用".to_string(),
                "录取".to_string(),
                "入职".to_string(),
            ],
            interview_keywords: vec![
                "面试".to_string(),
                "interview".to_string(),
                "面谈".to_string(),
            ],
            written_exam_keywords: vec![
                "笔试".to_string(),
                "测试".to_string(),
                "test".to_string(),
                "exam".to_string(),
            ],
            resume_keywords: vec![
                "简历".to_string(),
                "申请".to_string(),
                "投递".to_string(),
                "resume".to_string(),
                "apply".to_string(),
                "应聘".to_string(),
                "求职".to_string(),
            ],
        }
    }

    /// 对邮件主题进行分类，返回对应的阶段
    /// 遵循优先级规则：Offer > 面试 > 笔试 > 投递
    /// 如果无法匹配任何关键词，返回 None
    pub fn classify(&self, subject: &str) -> Option<Stage> {
        if subject.is_empty() {
            warn!("Empty subject received for classification");
            return None;
        }

        let subject_lower = subject.to_lowercase();

        // 按优先级从高到低检查
        if self.contains_any_keyword(&subject_lower, &self.offer_keywords) {
            info!("Classified as Offer: {}", subject);
            return Some(Stage::Offer);
        }
        if self.contains_any_keyword(&subject_lower, &self.interview_keywords) {
            info!("Classified as Interview: {}", subject);
            return Some(Stage::Interview);
        }
        if self.contains_any_keyword(&subject_lower, &self.written_exam_keywords) {
            info!("Classified as WrittenExam: {}", subject);
            return Some(Stage::WrittenExam);
        }
        if self.contains_any_keyword(&subject_lower, &self.resume_keywords) {
            info!("Classified as Resume: {}", subject);
            return Some(Stage::Resume);
        }

        warn!("Unclassified subject: {}", subject);
        None
    }

    /// 检查主题是否包含任意一个关键词
    fn contains_any_keyword(&self, subject: &str, keywords: &[String]) -> bool {
        keywords.iter().any(|keyword| subject.contains(keyword))
    }
}

// 定义漏斗分析器，负责核心分析逻辑
