    classifier: Arc<KeywordClassifier>,  // 使用 Arc 实现共享
}

// 确保 FunnelAnalyzer 可以在多线程环境下安全使用
unsafe impl Send for FunnelAnalyzer {}
unsafe impl Sync for FunnelAnalyzer {}

impl FunnelAnalyzer {
    pub fn new(classifier: KeywordClassifier) -> Self {
        FunnelAnalyzer {
            classifier: Arc::new(classifier),
        }
    }

    /// 分析邮件列表，返回按漏斗顺序排列的阶段计数
    /// 输入：邮件列表
    /// 输出：按漏斗顺序排列的 (阶段, 数量) 键值对列表
    pub fn analyze(&self, items: &[MailItem]) -> Vec<(Stage, usize)> {
        // 初始化所有阶段计数为 0
        let mut counts: std::collections::HashMap<Stage, usize> = Stage::all_in_order()
            .map(|stage| (stage, 0))
            .collect();

        // 遍历每封邮件进行分类计数
        for item in items {
            // 主题为空时不纳入分析
            if item.subject.is_empty() {
