            if let Some(stage) = self.classifier.classify(&item.subject) {
                *counts.get_mut(&stage).unwrap() += 1;
            }
            // 无法匹配的邮件被视为非招聘邮件，不纳入统计
        }

        // 按漏斗顺序输出结果
        Stage::all_in_order()
            .map(|stage| (stage, counts[&stage]))
            .collect()
    }
}

